const float EPS = 0.001;
const vec3 lightDir = vec3(0.5, 1, 0.25);
const vec3 lightColor = vec3(1.0, 1.0, 1.0);
const vec3 ambient = vec3(0.4, 0.4, 0.4);

vec3 cameraPos;

struct Ray
{
    vec3 Pos;
    vec3 Dir;
    vec4 Color;
    float Offset;
};

// https://iquilezles.org/articles/distfunctions/
float sdSphere( vec3 p, vec3 p2, float s )
{
      return length(p - p2)-s;
}

// https://www.shadertoy.com/view/4lVXRm
mat3 camRotation( vec2 m )
{
    m.y = -m.y;

    vec2 s = sin(m);
    vec2 c = cos(m);
    mat3 rotX = mat3(1.0, 0.0, 0.0, 0.0, c.y, s.y, 0.0, -s.y, c.y);
    mat3 rotY = mat3(c.x, 0.0, -s.x, 0.0, 1.0, 0.0, s.x, 0.0, c.x);

    return rotY * rotX;
}

// http://blog.hvidtfeldts.net/index.php/2011/09/distance-estimated-3d-fractals-v-the-mandelbulb-different-de-approximations/
float mandelBulb(vec3 pos) {
    float Power = 6.0 + sin(iTime * 0.5) * 2.0;
	vec3 z = pos;
	float dr = 1.0;
	float r = 0.0;
	for (int i = 0; i < 4 ; i++) {
		r = length(z);
		if (r>1.15) break;

		// convert to polar coordinates
		float theta = acos(z.z/r);
		float phi = atan(z.y,z.x);
		dr =  pow( r, Power-1.0)*Power*dr + 1.0;

		// scale and rotate the point
		float zr = pow( r,Power);
		theta = theta*Power;
		phi = phi*Power;

		// convert back to cartesian coordinates
		z = zr*vec3(sin(theta)*cos(phi), sin(phi)*sin(theta), cos(theta));
		z+=pos;
	}
	return 0.5*log(r)*r/dr;
}

float sceneDist(in vec3 p)
{
    return mix(mandelBulb(p), sdSphere(p, vec3(0, 0, 0), 1.0), max(sin(iTime * 0.25), 0.0));
}

// https://michaelwalczyk.com/blog-ray-marching.html
vec3 sceneNormal(in vec3 p)
{
    const vec3 small_step = vec3(0.001, 0.0, 0.0);

    float gradient_x = sceneDist(p + small_step.xyy) - sceneDist(p - small_step.xyy);
    float gradient_y = sceneDist(p + small_step.yxy) - sceneDist(p - small_step.yxy);
    float gradient_z = sceneDist(p + small_step.yyx) - sceneDist(p - small_step.yyx);

    vec3 normal = vec3(gradient_x, gradient_y, gradient_z);

    return normalize(normal);
}

// https://learnopengl.com/Lighting/Basic-Lighting
vec3 lightScene(in vec3 pos)
{  
    // Diffuse
    vec3 norm = normalize(sceneNormal(pos));
    float diff = max(dot(norm, lightDir), 0.0);
    vec3 diffuse = diff * lightColor;

    // Specular
    vec3 viewDir = normalize(cameraPos - pos);
    vec3 reflectDir = reflect(-lightDir, norm);

    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
    vec3 specular = 0.002 * spec * lightColor;  

    return (ambient + diffuse + specular);
}

void march(inout Ray ray)
{
    float totalDist = 0.0;
    for(int i = 0; i < 100; i++)
    {
        float dist = sceneDist(ray.Pos);

        if(dist < EPS)
        {
           ray.Color = vec4(vec3(0.45, 0.75, 0.85) * lightScene(ray.Pos), 1);
           break;
        }

        float travel = min(dist, 0.025);
        ray.Pos += ray.Dir * (travel * ray.Offset);
        totalDist += travel;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    float div = (iResolution.x / iResolution.y);
    vec2 sUV = vec2((uv.x * div) - 0.4, uv.y);

    float rot = iTime * 0.2;
    cameraPos = vec3(-sin(rot) * 2.0, 0, -cos(rot) * 2.0);
    mat3 cameraDir = camRotation(-vec2(rot, 0));

    Ray ray;
    ray.Pos = cameraPos;
    ray.Dir = vec3((sUV * 2.0 - 1.0), 1) * cameraDir;
    ray.Dir = normalize(ray.Dir);
    ray.Offset = (length(texture(iChannel0, uv * 1.0)) * 0.1) + 1.0;
    ray.Color = vec4(ambient, 1);

    march(ray);

    fragColor = vec4(ray.Color.xyz,1.0);
}
